/** The registry above, with its placeholder folders filled in. */
export function deployBd192c7State(folders: { homes: string; claudeHomes: string; piHomes: string; oldPiHomes: string }) {
  const text = JSON.stringify(DEPLOY_BD192C7_STATE).replaceAll('"/HOMES', JSON.stringify(folders.homes).slice(0, -1))
    .replaceAll('"/CLAUDEHOMES', JSON.stringify(folders.claudeHomes).slice(0, -1))
    .replaceAll('"/OLDPIHOMES', JSON.stringify(folders.oldPiHomes).slice(0, -1))
    .replaceAll('"/PIHOMES', JSON.stringify(folders.piHomes).slice(0, -1));
  return JSON.parse(text) as Record<string, unknown> & {
    chains: Array<{ id: string; steps: Array<{ source: string; accountId: string | null; modeId: string | null }> }>;
    accounts: Array<{ id: string; home: string | null }>;
    agentChains: Record<string, unknown>;
    links: Record<string, unknown>;
    bindings: Record<string, unknown>;
    claudeHomes: { dir: string | null; from: string[] };
    defaultChain: string | null;
  };
}
